local function _decode(str, k)
    local res = {}
    local b_xor = (bit32 and bit32.bxor) or function(a, b)
        local r, m = 0, 1
        while a > 0 or b > 0 do
            if a % 2 ~= b % 2 then r = r + m end
            a, b, m = math.floor(a / 2), math.floor(b / 2), m * 2
        end
        return r
    end
    local i = 1
    for b in str:gmatch("\\%d+") do
        local byte = tonumber(b:sub(2))
        res[i] = string.char(b_xor(byte, k))
        i = i + 1
    end
    return table.concat(res)
end

local success, result = pcall(function()
    return loadstring(_decode(_s, _k))()
end)

